def link(t,to,n='arrow',kind=''):return f'<a class="btn {kind}" href="{to}.html">{icon(n)}<span>{t}</span></a>'
def subhead(title,sub):return f'<header><div class="row"><h1>{title}</h1><a class="iconbtn" aria-label="View programme settings" href="programme.html">{icon("settings")}</a></div><p>{sub}</p></header>'
def bottom():return '<nav class="bottom">'+''.join(f'<a href="{to}.html" class="{cl}">{icon(i)}<span>{t}</span></a>' for to,i,t,cl in [('dashboard','sun','Today',''),('workload','calendar','Schedule',''),('assignment','tasks','Tasks',''),('roadmap','book','PGCE file','current')])+'</nav>'
def savepage(n,title,body,desktop=False):
 labels[n]={'title':title,'desktop':desktop}
 (D/f'{n}.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+title+' — proposed PGCE workspace</title><link rel="stylesheet" href="design.css"><body>'+body+'</body></html>')
def phone(n,title,sub,body):savepage(n,title,'<main class="mobile">'+subhead(title,sub)+body+'</main>'+bottom())
def item(title,sub,n='check',tone='teal',tagtext=None):return f'<div class="item"><span class="tile {tone}">{icon(n)}</span><div class="grow"><h3>{title}</h3><p>{sub}</p>{tag(tagtext,tone) if tagtext else ""}</div></div>'
def stage(labels,selected):return '<div class="steps">'+''.join(f'<span class="step {"current" if i==selected else ""}">{t}</span>' for i,t in enumerate(labels))+'</div>'
def field(t,v):return '<span class="label">'+t+'</span><div class="fauxinput">'+v+'</div>'
